declare(strict_types=1);

return [
    'mission_heading' => 'Missionen, Vorlagen und ihre Verbindung zu MECM',
    'mission_p1' => 'Eine Mission ist eine Gruppe zusammengehöriger VMs, die gemeinsam bereitgestellt werden. Wichtig zu wissen: Der Missionsname wird 1:1 als Gerätesammlung (Device Collection) in MECM angelegt, im Ordner „VirtuSphere_Missions“. Was hier im Portal steht, taucht also später genauso in der MECM-Konsole auf.',
    'mission_p2' => 'Vorlagen erkennt man am Namen, der mit „_“ beginnt. Sie sind reine Bauplan-Missionen: Sie werden nie an MECM übertragen und dürfen als einzige VM-Namen doppelt verwenden. Aus einer Vorlage entsteht jederzeit eine echte Mission, mit frischen VM-IDs und leeren MAC-Adressen: Im Abschnitt „In Mission kopieren“ auf der Detailseite der Vorlage den Ziel-Missionsnamen eintragen und „Kopieren“ wählen.',
    'mission_p3' => 'Die Übergabe an MECM passiert automatisch: Sobald eine VM eine MAC-Adresse hat (nach der Bereitstellung über ESXi), importiert sie das Sync-Skript auf dem MECM-Server als Gerät und ordnet sie ihrer Missions-Collection zu. Niemand muss VMs von Hand in MECM anlegen.',
    'mission_p4' => 'In die andere Richtung gilt das nicht: Das Löschen einer VM oder Mission im Portal ist rein lokal. Das Gerät und seine Collection-Mitgliedschaften bleiben in MECM bestehen und werden dort von Hand entfernt, wenn sie weg sollen. Der Sync gleicht nur die eigenen, im Portal noch zugewiesenen Regeln ab; von Hand in MECM angelegte Regeln fasst er nie an.',
    'edit_conflict_heading' => 'Gleichzeitige Bearbeitung',
    'edit_conflict_p1' => 'Wird dieselbe Mission oder VM nach dem Öffnen der Seite geändert, lehnt VirtuSphere den eigenen veralteten Stand ab. Laden Sie die Seite neu, prüfen Sie die aktuelle Konfiguration und geben Sie Ihre Änderung erneut ein. So überschreibt auch eine Änderung innerhalb derselben Sekunde keine inzwischen gespeicherten Felder, Netzwerkkarten, Festplatten oder Paketzuordnungen.',
    'work_context_heading' => 'Zur Missions- oder VM-Liste zurückkehren',
    'work_context_p1' => 'Wer aus einer sortierten Missions- oder Vorlagenliste Missionsdetails, eine VM-Liste oder einen VM-Editor öffnet, nimmt diesen Listenkontext in den Links mit. Zurück führt zu demselben Listentyp, Filter und derselben Reihenfolge. Eine gespeicherte VM kehrt in die vorherige VM-Sortierung zurück. Die ursprüngliche Zeile erhält den Fokus, solange sie noch existiert.',
    'work_context_p2' => 'Der Kontext gehört zur Adresse des offenen Tabs. Zwei Tabs können deshalb unterschiedliche Listen und Sortierungen verwenden, ohne einander zu überschreiben. Zurück und Vorwärts im Browser sowie das Öffnen einer Zeile in einem neuen Tab bleiben nutzbar. Ohne JavaScript gelten dasselbe serverseitige Ziel und dasselbe Zeilenfragment; JavaScript ergänzt nur den Tastaturfokus.',
    'work_context_p3' => 'Übertragen werden nur bekannte Werte für Listentyp, Filter und Sortierung. Formularinhalte, Mehrfachauswahlen, Passwörter und Sicherheitstoken gehören nicht dazu. Ein direkter oder alter Link ohne Kontext öffnet die normale übergeordnete Liste; Berechtigungen und das Vorhandensein des Objekts werden an jedem Ziel erneut geprüft.',
    'unsaved_p1' => 'Die Missionseinstellungen und der VM-Editor melden außerdem ungespeicherte Änderungen und warnen, bevor ein Link oder eine Browsernavigation sie verwirft. Die Warnung speichert nichts: Nach einem Validierungs- oder Bearbeitungskonflikt das Formular prüfen und erneut bewusst speichern.',
    'effective_heading' => 'Wirksame Sollwerte und ihre Herkunft',
    'effective_p1' => 'Der VM-Editor fasst zusammen, welche Datastore-, Datacenter- und Autostartwerte die nächste passende Bereitstellungsaktion verwendet. Dabei unterscheidet er eine VM-Überschreibung von einem aus der Mission übernommenen Wert. Es sind Sollwerte, keine Behauptung über den aktuellen Zustand auf ESXi.',
    'effective_p2' => 'Ein leerer VM-Datastore oder ein leeres VM-Datacenter bedeutet „von Mission übernehmen“. Geben weder VM noch Mission ein Datacenter vor, lässt es sich erst aus dem später auf der Bereitstellungsseite gewählten ESXi-Host auflösen; der Editor nennt es deshalb noch nicht bestimmt, statt ha-datacenter zu erfinden. Für den Datastore gibt es keinen solchen Hostfallback.',
    'effective_p3' => '„Missionswert verwenden“ leert nur die zugehörige VM-Überschreibung im offenen Formular und speichert nicht sofort. Eine leere Autostartverzögerung übernimmt die Missionsverzögerung, während 0 ausdrücklich keine Wartezeit bedeutet. Ist Autostart in der Mission aus, bleibt die VM-Einstellung erhalten, kann aber erst nach Einschalten der Mission wirksam werden.',
    'naming_heading' => 'Namensregeln & Datenqualität',
    'naming_p0' => 'Alles, was im Portal angelegt wird, muss später in Windows und MECM 1:1 funktionieren. Daraus ergeben sich diese Regeln:',
    'naming_p1' => 'Missionsname: keine Leerzeichen. Sobald eine VM der Mission in MECM registriert ist, ist der Name gesperrt und kann nicht mehr geändert werden, denn er ist gleichzeitig der Name der MECM-Collection, und eine Umbenennung würde diese Verbindung brechen. Wer umbenennen will, muss es also vor der MECM-Registrierung tun.',
    'naming_p2' => 'VM-Name in ESXi: muss über alle Missionen hinweg eindeutig sein, damit eine VM im Portal, im Auftragsprotokoll und in ESXi dieselbe bleibt. Das ist nicht der MECM-Gerätename: Den liefert der Windows-Hostname. Nur Vorlagen dürfen Namen doppeln; beim Klonen einer Vorlage listet das Portal vorab alle Namen auf, die kollidieren würden.',
    'naming_p3' => 'Windows-Hostname: ist der spätere Windows-Computername (NetBIOS) und muss dessen Regeln erfüllen: höchstens 15 Zeichen, nur Buchstaben, Zahlen und Bindestriche im Inneren, keine Punkte. Hintergrund: Der Client würde beim Deploy still kürzen und bereinigen, und dann weicht der echte Name vom eingetragenen ab. Ältere Bestandswerte, die die Regel verletzen, bleiben gültig und zeigen eine Warnung am Feld; erst bei einer Änderung greift die Regel. Eine Ausnahme gilt für grob fehlerhafte Bestandswerte: leere Namensteile durch doppelte Punkte oder ein Bindestrich am Anfang oder Ende eines Namensteils. Sie werden auch unverändert abgelehnt und müssen beim nächsten Speichern korrigiert werden.',
    'naming_p4' => 'MAC-Adressen: Dieselbe Adresse wird je nach Werkzeug unterschiedlich geschrieben. Mit Doppelpunkten (00:50:56:AB:CD:EF, so zeigt ESXi sie), mit Bindestrichen (00-50-56-AB-CD-EF, so gibt Windows sie in „ipconfig /all“ aus) oder in der Cisco-Punktschreibweise (0050.56ab.cdef). Alle drei meinen dieselbe Adresse. Das Portal speichert intern immer die Doppelpunkt-Form in Großbuchstaben, egal wie die Adresse eingetippt oder importiert wurde. Der Bindestrich in einer MAC ist also nur ein Trennzeichen und macht keinen Unterschied. Portgruppennamen sind dagegen exakte ESXi-Namen: Groß- und Kleinschreibung bleibt erhalten. Der automatische MAC-Import akzeptiert nur die eine Netzwerkkarte, deren Portgruppe exakt dem Missionswert „WDS-Portgruppe (PXE)“ entspricht, und lehnt Dubletten oder mehrdeutige Ziele ab, statt still eine falsche Zuordnung zu erzeugen.',
    'status_heading' => 'VM-Status: Phase und Befund',
    'status_p1' => 'Die VM-Liste und die VM-Übersicht zeigen je VM eine Phase und den schwersten Befund. Beides wird beim Lesen aus gespeicherten Belegen abgeleitet; nichts davon wird gespeichert oder an MECM übertragen.',
    'status_p2' => 'Eine Phase wird nur für eine Meldung vergeben, die angekommen ist. Sie sagt, welcher Beleg zuletzt da war, nicht wie viel Arbeit fertig ist. Ein fehlgeschlagener Auftrag setzt die Phase nicht zurück; er erscheint als Befund.',
    'status_phase_created' => 'Angelegt: die VM steht im Portal (angelegt, importiert oder aus einer Vorlage kopiert). Auf ESXi existiert noch nichts.',
    'status_phase_in_progress' => 'In Arbeit: ein Bereitstellungsauftrag hat die VM markiert. Der Befund „Auftrag läuft“ führt zum Protokoll.',
    'status_phase_on_esxi' => 'Auf ESXi: Create oder der MAC-Export hat die Instanz-UUID der VM gebunden.',
    'status_phase_mac_known' => 'MAC bekannt: der Ansible-Host hat die MAC-Adressen zurückgemeldet, oder die VM wurde nach „MECM-ID zurücksetzen“ erneut vorgemerkt. MECM kennt sie noch nicht.',
    'status_phase_handed_to_mecm' => 'An MECM übergeben: der Device-Sync hat die VM importiert und ihre ResourceID zurückgemeldet. Ob PXE lief, belegt erst die Beobachtung; bis dahin steht der Befund „PXE-Beleg fehlt“.',
    'status_phase_windows_reports' => 'Windows meldet sich: das Portal hat den Client-Ready-ACK angenommen. Hostname, IP-Umstellung und Datenträger laufen danach.',
    'status_phase_client_done' => 'Client fertig: alle vier Clientphasen haben als letztes Ereignis „abgeschlossen“ gemeldet (best effort).',
    'status_template' => 'Vorlagen-VMs zeigen „Vorlage“ und keinen Befund; sie werden nie bereitgestellt.',
    'status_technical_heading' => 'Technisch',
    'status_technical_p1' => 'Gespeichert bleiben drei Werte: der Lebenszyklus, der MECM-Abgleich und der Stufenwert x/5, den die MECM-Schnittstelle liest. Der Stufenwert ist als Tooltip der Phase sichtbar und steht im VM-Editor. Auf der Leitung wird er aus den beiden Achsen berechnet; deshalb kann dort 1/5 erscheinen, das kein Schreiber speichert.',
    'status_findings_heading' => 'Befunde und nächster Schritt',
    'status_findings_p1' => 'Die Liste zeigt den schwersten Befund mit Link auf den nächsten Schritt und „+n“ für weitere; der VM-Editor zeigt alle. Reihenfolge ist die Schwere, nicht die Zeit.',
    'status_finding_create_uncertain' => 'Create ungeklärt: das Ergebnis einer Create-Einheit auf dem Host ist unbekannt. Nächster Schritt: Auftragsprotokoll und Create-Karte, nichts erneut anlegen.',
    'status_finding_job_failed' => 'Auftrag fehlgeschlagen: der Lebenszyklus steht auf fehlgeschlagen; der jüngste Auftrag dieser VM nennt Modus und Zeit. Ist die VM in diesem Auftrag nicht angelegt worden, heißt der Befund „Auf ESXi nicht angelegt“ und führt direkt zu ihrer Fehlerzeile im Protokoll. Nächster Schritt: Auftragsprotokoll.',
    'status_finding_missing_from_inventory' => 'Nicht mehr im Inventar: das frische Inventar des gebundenen Zugangs kennt die Instanz-UUID nicht. Nächster Schritt: ESXi-Karte im Systemstatus.',
    'status_finding_job_running' => 'Auftrag läuft: ein Auftrag arbeitet an dieser VM. Nächster Schritt: Auftragsprotokoll.',
    'status_finding_old_mecm_device' => 'Altes MECM-Gerät löschen: nach „MECM-ID zurücksetzen“ existiert das alte Gerät in MECM weiter. Nächster Schritt: in der MECM-Konsole löschen, dann die MECM-Karte im Systemstatus prüfen.',
    'status_finding_mecm_pending_overdue' => 'Wartet auf MECM länger als :hours h: der Device-Sync hat die VM nicht gebunden. Nächster Schritt: Ursachenzeile der MECM-Karte im Systemstatus.',
    'status_finding_mecm_pending' => 'Wartet auf MECM: die VM ist vorgemerkt, der nächste Lauf des Device-Sync holt sie.',
    'status_finding_powered_off' => 'Laut Inventar ausgeschaltet: das frische Inventar meldet die VM ausgeschaltet, obwohl MECM oder Windows arbeiten sollten. Nächster Schritt: VM-Editor und ESXi prüfen.',
    'status_finding_os_install_overdue' => 'OS-Installation länger als :hours h beobachtet: die Beobachtung läuft ohne Abschluss. Nächster Schritt: im VM-Editor prüfen und die Beobachtung bewusst neu starten.',
    'status_finding_pxe_unwatched' => 'PXE-Beleg fehlt: MECM kennt die VM, ob sie per PXE gebootet hat, ist unbelegt. Nächster Schritt: im VM-Editor „PXE jetzt beobachten“, sobald PXE ausgelöst wurde.',
    'status_finding_os_install_watching' => 'Beobachtung läuft: die PXE-Beobachtung ist gestartet und nicht überfällig.',
    'status_finding_client_phase_failed' => 'Clientphase fehlgeschlagen: der Client hat eine Phase als fehlgeschlagen gemeldet. Nächster Schritt: Abschnitt Clientphasen im VM-Editor.',
    'status_finding_client_phase_unconfirmed' => 'Clientphase unbestätigt: eine Phase wurde gestartet und seit :minutes Minuten nicht abgeschlossen. Nächster Schritt: VM-Editor und Clientprotokoll.',
    'status_finding_package_run_failed' => 'Paketbericht fehlgeschlagen: der letzte abgeschlossene Paketlauf meldet einen Fehler. Nächster Schritt: Paketbericht.',
    'status_finding_mecm_sync_failed' => 'MECM-Abgleich offen nach Fehler: ein Auftrag hat die VM als fehlgeschlagen markiert; der Abgleich ist seitdem nicht neu gelaufen. Nächster Schritt: Auftragsprotokoll.',
    'status_stuck_heading' => 'Wenn eine VM hängen bleibt',
    'status_stuck_1' => 'Befund „Create ungeklärt“ oder „Auftrag fehlgeschlagen“: Der Link öffnet das Auftragsprotokoll. Bei „Create ungeklärt“ zuerst auf dem Host prüfen, ob die VM existiert, und nichts erneut anlegen. Steht die VM ohne Befund auf „Angelegt“ oder „Auf ESXi“, lief noch kein Auftrag mit MAC-Export, oder er hat die MAC-Adressen nicht zurückgemeldet; ohne MAC-Rückmeldung geht es nicht weiter.',
    'status_stuck_2' => 'Phase „MAC bekannt“ mit Befund „Wartet auf MECM“: Die WDS/PXE-MAC ist da, MECM hat die VM aber nicht importiert. Erst auf „VM bearbeiten“ prüfen, ob genau eine Netzwerkkarte den exakten Missionswert „WDS-Portgruppe (PXE)“ trägt. Der Devices Sync importiert die MAC genau dieser Karte; trägt keine oder mehr als eine Karte den Wert, überspringt er die VM, und die Ursachenzeile im Systemstatus nennt den Grund. Dann im Systemstatus nachsehen, ob „MECM Device-Sync“ auf „OK“ steht und ob die Karte Datenwarnungen zählt: fehlt eine Collection der VM, bleibt sie absichtlich in der Warteschlange und die Ursachenzeile nennt sie. Nach :hours Stunden wird daraus der Befund „Wartet auf MECM … länger als :hours h“; er ändert nichts und lässt sich nach der Prüfung bewusst neu starten. Vorlagen werden grundsätzlich nicht an MECM übertragen.',
    'status_stuck_3' => 'Phase „An MECM übergeben“ mit Befund „PXE-Beleg fehlt“, „Beobachtung läuft“ oder „OS-Installation länger als :hours h beobachtet“: Ab hier arbeitet die VM selbst. Erst wenn PXE tatsächlich ausgelöst wurde, im VM-Editor „PXE jetzt beobachten“ wählen; nach :hours Stunden ohne Abschluss erscheint der Befund. Die Zeitwarnung setzt die VM nie auf fehlgeschlagen und löscht nichts.',
    'status_stuck_4' => 'Phase „Windows meldet sich“ mit Befund „Clientphase fehlgeschlagen“, „Clientphase unbestätigt“ oder „Laut Inventar ausgeschaltet“: Clientphasen und Zeitleiste im VM-Editor öffnen. Fehlende oder stehen gebliebene Phasen sind Diagnosehinweise, kein Beweis (frühe Abbrüche, verlorene best-effort-Meldungen). Zusätzlich MECM-Application-Detection, Erreichbarkeit und das lokale Clientprotokoll prüfen. „Laut Inventar ausgeschaltet“ gilt nur für ein frisches Inventar und nennt dessen Zeitpunkt.',
    'disktype_heading' => 'Festplattentypen',
    'disktype_p1' => 'Jede Festplatte einer VM hat einen Typ. Er legt fest, wie ESXi den Platz auf dem Datastore belegt, und wirkt nur beim Erstellen der VM.',
    'disktype_thin' => 'Thin: die Platte belegt zunächst nur den tatsächlich geschriebenen Teil und wächst mit dem Bedarf. Das spart Platz, macht ein Überbuchen des Datastore aber leicht, und ein erster Schreibzugriff muss den Block zusätzlich bereitstellen.',
    'disktype_thick' => 'Thick (Lazy Zeroed): der volle Platz ist ab dem Erstellen reserviert. Die einzelnen Blöcke werden aber erst beim ersten Schreibzugriff genullt.',
    'disktype_eager' => 'Eager Zeroed Thick: der volle Platz ist reserviert und bereits vorab genullt. Diese Arbeit fällt damit beim Anlegen an statt beim ersten Schreibzugriff.',
    'disktype_p2' => 'Vorbelegt ist :default. Die drei Typen unterscheiden sich darin, wann die Arbeit anfällt. Wie stark sich das auswirkt, hängt vom Storage, von dessen VAAI- oder NFS-Unterstützung, von der Plattengröße und von der Last ab; eine feste Rangfolge gibt es nicht. Ob der Storage den angeforderten Typ genau so umsetzt, liest das Portal nicht zurück und behauptet es deshalb auch nicht.',
    'disktype_p3' => 'Betrieblich zählt vor allem die Anlegezeit: Eager Zeroed Thick kann das Erstellen großer oder mehrerer Platten deutlich verlängern und dabei die Zeitbudgets der Automatisierung erreichen. Thin und Lazy Zeroed Thick vermeiden dieses Risiko nicht pauschal, sie verschieben die Arbeit nur. Zu den Budgets: ein entfernter Schritt gilt als gescheitert, wenn er :minutes Minuten lang überhaupt keine Ausgabe liefert. Beim Erstellen fragt VirtuSphere jede VM einzeln und regelmäßig nach ihrem Zustand, deshalb sieht eine lange laufende Platte nicht mehr wie Stille aus. Die Gesamtstrecke des Erstellens bleibt trotzdem auf :hours Stunden begrenzt; wie lange eine einzelne Platte tatsächlich braucht, hängt vom Host und vom Datastore ab und wird hier bewusst nicht als Zahl behauptet. Eine Umstellung des Typs wirkt nur beim Erstellen; bestehende VMs und bereits angelegte Festplatten werden dadurch nicht konvertiert.',
    'vm_delete_heading' => 'VM außer Betrieb nehmen',
    'vm_delete_p1' => 'Das Portal löscht bewusst nie automatisch nach außen: weder die VM auf dem ESXi-Host noch das Gerät in MECM. Beides bleibt eine bewusste, manuelle Entscheidung. Deshalb sind es immer drei Schritte:',
    'vm_delete_step1' => '1. VM auf dem ESXi-Host ausschalten und löschen (Host-Client oder vCenter). Das Portal tut das nie von selbst; wird dieser Schritt vergessen, läuft die Maschine dort weiter und belegt weiterhin Datastore-Speicher.',
    'vm_delete_step2' => '2. VM im Portal löschen. Damit verschwinden automatisch der Datenbankeintrag, die Netzwerkkarten, die Paket-Verknüpfungen und die Status-Historie.',
    'vm_delete_step3' => '3. In der MECM-Konsole das Gerät löschen (Assets and Compliance → Devices). Wird eine Mission komplett aufgelöst, zusätzlich die zugehörige Collection im Ordner „VirtuSphere_Missions“ entfernen.',
    'vm_delete_p2' => 'Wird Schritt 3 vergessen, passiert erst einmal nichts Schlimmes. Aber sobald eine neue VM mit demselben Namen und einer anderen MAC angelegt wird, meldet der Device-Sync einen MAC-Konflikt im Protokoll und übernimmt die neue VM nicht automatisch.',
    // Etappe 14D: Zwei Namen, ein eingefrorener Rolloutname und genau ein
    // Aktivierungspunkt. Die drei Saetze beantworten die Fragen, die der VM-Editor
    // allein nicht beantworten kann.
    'rollout_heading' => 'Der Windows-Hostname und der Rollout',
    'rollout_p1' => 'Eine VM trägt zwei Namen, und sie tun verschiedene Dinge. Der „VM-Name in ESXi“ identifiziert die virtuelle Maschine im Portal, im Auftragsprotokoll und auf dem ESXi-Host. Der „Windows-Hostname“ ist der Name, den der fertige Windowsrechner trägt und unter dem MECM ihn als Gerät führt. Nur der zweite geht an MECM.',
    'rollout_p2' => 'Solange eine VM noch nicht an MECM übergeben wurde, folgt der Rolloutname jeder Änderung am Windows-Hostnamen sofort. Mit der ersten Übergabe friert er ein: MECM, Windows und der Client handeln ab da nach diesem Namen, und eine Korrektur im Portal darf ein bereits übergebenes Gerät nicht hinter ihrem Rücken umdeuten. Der VM-Editor zeigt in diesem Fall beide Namen nebeneinander an, und die VM-Liste zeigt in der Hostnamenzelle das Badge „wartet auf Reset“.',
    'vm_steps_heading' => 'VM anlegen und bearbeiten',
    'vm_steps_intro' => 'Eine VM gehört immer zu einer Mission. So legen Sie eine VM an und speichern sie:',
    'vm_steps_1' => '1. Die Mission unter „Missionen“ öffnen und über „VMs“ die VM-Liste aufrufen.',
    'vm_steps_2' => '2. „VM hinzufügen“ wählen. Eine bestehende VM öffnen Sie in derselben Liste über „Bearbeiten“.',
    'vm_steps_3' => '3. Pflichtfelder: „VM-Name in ESXi“ (höchstens :max Zeichen, nur Buchstaben, Zahlen und Bindestriche im Inneren) und „OS“.',
    'vm_steps_4' => '4. „Windows-Hostname“ nach den Namensregeln oben (keine Punkte). Bleibt das Feld leer, übernimmt die VM den VM-Namen.',
    'vm_steps_5' => '5. Netzwerkkarten unter „Schnittstellen“: Mindestens eine ist Pflicht. „Schnittstelle hinzufügen“ legt eine an. Beim Speichern braucht jede Karte ein VLAN, und zwei Karten derselben VM dürfen nicht dasselbe VLAN haben.',
    'vm_steps_6' => '6. Festplatten unter „Datenträger“ sind optional. Ohne eigene Festplatte erhält die VM die Standard-Festplatte.',
    'vm_steps_7' => '7. Pakete unter „Pakete“ sind optional. Zurückgezogene Pakete bietet der Editor nicht an; bereits verknüpfte bleiben sichtbar.',
    'vm_steps_8' => '8. „VM speichern“ wählen. Erst danach sind die Änderungen gespeichert.',
    'vm_steps_note' => 'Die Netzwerkkarten einer VM lassen sich nicht ändern, solange ein laufender Bereitstellungsauftrag dieser Mission die VM umfasst. Ist Datastore oder Datacenter leer, übernimmt die VM den Wert der Mission.',
    'vm_steps_mecm' => 'Ist die VM bereits in MECM registriert, überträgt jedes Speichern automatisch, was MECM von der Paketauswahl noch nicht hat, auch aus einer früheren Änderung. Erforderliche Pakete installiert der Client beim nächsten Richtlinienabruf. Entfernte Pakete werden in MECM nur ausgetragen; installierte Software bleibt unverändert.',
    'vm_steps_mecm_os' => 'Weicht das Betriebssystem der VM von dem ab, das MECM für sie hält, fragt das Speichern vorher nach, weil eine Übertragung eine Neuinstallation auslösen kann. „Speichern und an MECM übertragen“ überträgt dann den ganzen Sollstand der VM. „Nur im Portal speichern“ lässt MECM unverändert, bis Sie die Übertragung bewusst auslösen.',
    'domain_p1' => 'Die Domäne der Mission ist ein vollständiger DNS-Name mit mindestens einem Punkt, zum Beispiel corp.example.local. Sie ist die Vorgabe für die Domäne der VMs. Beim Speichern der Missionseinstellungen sind Datastore und Domäne Pflicht; bei einer Vorlage bleiben beide optional.',
    'status_axes_heading' => 'Die beiden Achsen in der VM-Liste und im Editor',
    'status_axes_p1' => 'Die Spalte „MECM“ bleibt neben Phase und Befund stehen: sie zeigt die zweite gespeicherte Achse, den Abgleich mit MECM. Der VM-Editor zeigt zusätzlich den Lebenszyklus.',
    'status_axes_mecm_not_ready' => 'Noch nicht bereit: Die VM ist für MECM noch nicht vorgesehen. So beginnen neue VMs; hier ist nichts zu tun.',
    'status_axes_mecm_pending' => 'Wartet auf MECM: Die VM ist für die Übernahme in MECM vorgemerkt, zum Beispiel nach „MECM-ID zurücksetzen“. Der Device-Sync hat sie noch nicht gebunden. Nächster Schritt: im Systemstatus die Karte „MECM Device-Sync“ prüfen.',
    'status_axes_mecm_registered' => 'In MECM registriert: Der Device-Sync hat das Gerät importiert und gebunden; die MECM-ID ist gesetzt.',
    'status_axes_mecm_failed' => 'MECM-Abgleich offen nach Fehler: ein Bereitstellungsauftrag hat die VM als fehlgeschlagen markiert, und der Abgleich mit MECM ist seitdem nicht neu gelaufen. Das Auftragsprotokoll dieser Mission nennt die Ursache.',
    'status_axes_lifecycle' => 'Lebenszyklus (nur im Editor): In Vorbereitung, Bereit, Wird bereitgestellt, Bereitgestellt, Betriebssystem wird installiert, Betriebssystem installiert oder Fehlgeschlagen. Er zeigt, wo der Bereitstellungslauf steht.',
    'badges_heading' => 'Abzeichen in den Listen und im Editor',
    'badges_p1' => 'Die Abzeichen sagen, was zu prüfen ist. Keines ändert eine VM oder einen Auftrag.',
    'badge_mission_attention' => 'Spalte „Prüfung fällig“ der Missionsliste: Das Abzeichen nennt die Zahl der VMs der Mission, deren Fortschrittsbeobachtung überfällig ist.',
    'badge_vm_attention' => 'Spalte „Befund“ der VM-Liste: der schwerste Befund als Badge mit Link auf den nächsten Schritt, „+n“ führt zu den weiteren Befunden im VM-Editor. Die Zeitbefunde „Wartet auf MECM länger als :mecm_hours h“ und „OS-Installation länger als :install_hours h beobachtet“ ändern den Status nicht.',
    'badge_vm_editor' => 'Im VM-Editor zeigt „Prüfung fällig“ eine überfällige Beobachtung, „Beobachtung“ eine laufende. Die Schaltflächen heißen „PXE jetzt beobachten“ und „Beobachtung neu starten“.',
    'badge_network' => 'Spalte „Netzwerk“ der VM-Liste, Abzeichen „Netzwerk prüfen“: Eine Netzwerkkarte hat einen Befund, etwa eine fehlende, doppelte oder mehrdeutige Portgruppe. Der Tooltip nennt den Befund.',
    'badge_rollout' => 'Hostnamenzelle der VM-Liste, Abzeichen „wartet auf Reset“: Der Windows-Hostname weicht vom Rolloutnamen ab, unter dem MECM das Gerät führt. Der Abschnitt „Der Windows-Hostname und der Rollout“ erklärt den Weg.',
    'link_system_status' => 'Zum Systemstatus',
    'link_deploy' => 'Zur Bereitstellung',
    'rollout_p3' => 'Für einen neuen Rollout gibt es genau einen Weg, und er hat vier Schritte: den Windows-Hostnamen im Portal korrigieren, das alte Gerät in der MECM-Konsole löschen, bei einer neu erzeugten VM zuerst die neue PXE-MAC importieren lassen, und dann „MECM-ID zurücksetzen“ ausführen. Der Reset ist der einzige Punkt, an dem ein neuer Rolloutname wirksam wird; kein Bereitstellungsmodus tut das. Solange die Übergabe noch aussteht, lässt sich ein Tippfehler jederzeit korrigieren und erneut zurücksetzen.',
    'rollout_p4' => 'VirtuSphere löscht in MECM nichts, auch nicht beim Reset und nicht beim Löschen der VM. Solange das Gerät des vorherigen Rollouts dort noch existiert, sagt die VM das als offenen Punkt, und der Device-Sync importiert bewusst nicht. Vorlagen haben keinen Rolloutnamen: Erst beim Erzeugen einer echten Mission aus einer Vorlage entsteht einer, frisch aus dem gewünschten Windows-Hostnamen. Export und Import von Missionen übertragen nur den Sollwert, nie den eingefrorenen Rolloutnamen, die MECM-ID oder die MAC.',
    'transfer_heading' => 'Mission exportieren und importieren',
    'transfer_p1' => 'Auf der Detailseite einer Mission lässt sich diese als JSON-Datei exportieren (mit VMs, Netzwerkkarten, Festplatten und Paketverknüpfungen). Über die Missionsliste wird eine solche Datei wieder importiert und legt eine neue Mission an. Das ist ein Transportweg zwischen Umgebungen, kein Backup.',
    'transfer_p2' => 'MAC-Adressen und MECM-IDs werden nie mit exportiert oder importiert; importierte VMs starten frisch registriert. Der Missionsstatus aus der Datei wird ebenfalls nicht übernommen. Vor dem Import zeigt eine Vorschau die Anzahlen, den Exportzeitpunkt sowie alle blockierenden oder warnenden Befunde an.',
    'transfer_p3' => 'Den Import blockieren ausschließlich Befunde in der Datei selbst: fehlende VLANs, global bereits vergebene VM-Namen, ein Windows-Hostname, den bereits eine andere VM belegt, doppelte VM-Namen oder doppelte Windows-Hostnamen innerhalb derselben Datei, ungültige Angaben zur Mission oder zu einzelnen VMs sowie kaputte Listen und Einträge, die mit ihrer Position in der Datei genannt werden. Nur diese Befunde machen „Import bestätigen“ grau; sie lassen sich nur durch eine korrigierte Exportdatei und einen neuen Upload beheben. Die Vorschau ist :minutes Minuten gültig.',
    'transfer_p4' => 'Der Name der neuen Mission muss eindeutig sein und darf keine Leerzeichen enthalten. Ein Namensproblem wird direkt am Namensfeld der Vorschau gemeldet und macht „Import bestätigen“ nicht grau: Der Knopf bleibt bedienbar, ein anderer Name wird eingetragen und beim Bestätigen erneut geprüft. Die hochgeladene Datei darf höchstens :max groß sein.',
    'transfer_scope' => 'Übernommen wird nur, was das Exportformat kennt. Zusätzliche Felder in der Datei werden stillschweigend ignoriert und MAC-Adressen ohnehin nie übernommen; sie können den Import deshalb weder blockieren noch etwas verändern. Nicht gefundene Pakete werden nur gemeldet und beim Import übersprungen. Eine Paketverknüpfung ohne Namen blockiert dagegen, damit keine Verknüpfung unbemerkt verloren geht.',
    'transfer_session' => 'Pro Anmeldung gibt es genau eine aktive Vorschau. Ein neuer Upload ersetzt die vorherige; ein älterer Vorschaulink meldet dann nur, dass es dahinter nichts mehr gibt, und lässt die neue Vorschau unangetastet. „Abbrechen“ verlässt lediglich die Ansicht und verwirft den Zwischenstand nicht sofort: Solange die Vorschau gültig ist, zeigt der Zurück-Knopf des Browsers dieselbe Vorschau wieder.',
    'transfer_p5' => 'Der Knopf „CSV-Export“ über den Listen hat damit nichts zu tun: Er lädt nur die gerade angezeigte Tabelle herunter, etwa für Berichte in Excel. CSV-Dateien lassen sich nicht importieren; der Import akzeptiert ausschließlich die JSON-Datei aus dem Missions-Export.',
    'bulk_heading' => 'Mehrere VMs auf einmal',
    'bulk_p1' => 'In der VM-Liste lassen sich mehrere VMs per Kontrollkästchen auswählen und gemeinsam löschen oder ihre MECM-ID zurücksetzen. Löschen entfernt nur die Portal-Datensätze, nie etwas auf dem Hypervisor.',
    'bulk_p2' => 'Einzelne VMs werden übersprungen und im Ergebnis mit Grund genannt, etwa wenn die Mission gerade einen aktiven Deploy-Job hat oder einer VM der importierte MAC für „MECM-ID zurücksetzen“ fehlt. Pro Aktion sind höchstens :cap VMs möglich.',
    'hotplug_heading' => 'CPU/RAM-Hot-Add',
    'hotplug_p1' => 'Im VM-Editor lässt sich Hot-Add für CPU und RAM aktivieren (standardmäßig an). Das erlaubt später das Hinzufügen von CPU und RAM im laufenden Betrieb. Die Einstellung wirkt nur bei der Erzeugung der VM. Ein erneuter Create-Lauf schickt sie zwar auch an eine vorhandene VM, ob ESXi sie dort übernimmt, liest das Portal aber nicht zurück. Deshalb ist das kein verlässlicher Weg, die Einstellung nachträglich zu ändern. Das Gast-Betriebssystem muss Hot-Add unterstützen.',
    'creator_heading' => 'Ersteller von Missionen und VMs',
    'creator_p1' => 'Missionen, Vorlagen und VMs merken sich, wer sie angelegt hat. Der Name wird beim Anlegen aus der angemeldeten Sitzung übernommen und danach nicht mehr verändert; auch wer die VM später bearbeitet, bleibt nicht als Ersteller stehen. Das Feld ist deshalb nur lesbar und lässt sich nicht überschreiben.',
    'creator_p2' => 'Beim Kopieren richtet sich der Ersteller danach, wer die Arbeit ausgelöst hat:',
    'creator_capture' => 'Als Vorlage speichern: Die Vorlage gehört der Person, die gespeichert hat. Die mitgesicherten VMs behalten ihren ursprünglichen Ersteller.',
    'creator_clone' => 'In Mission kopieren: Die neue Mission und ihre VMs gehören der Person, die kopiert hat, nicht dem Autor der Vorlage.',
    'creator_import' => 'Mission aus einer Datei importieren: Die Mission gehört der importierenden Person. Die VMs behalten den Ersteller, der in der Datei steht.',
    'creator_unknown' => 'Steht im Feld „Unbekannt“, ist kein Ersteller hinterlegt. Das betrifft Missionen und VMs aus der Zeit vor dieser Funktion sowie alles, was seinerzeit über die inzwischen entfernte Desktop-Schnittstelle angelegt wurde: Dort meldete sich nur ein Token an, kein Benutzer. Ein Name wird in diesem Fall bewusst nicht geraten.',
    'location_heading' => 'Datacenter und Datastore',
    'location_p1' => 'Beide Felder sind Auswahllisten aus dem ESXi-Inventar. Beim Datastore steht hinter dem Namen der freie Speicher des letzten Abrufs, sofern der Abruf einen gemeldet hat; steht dort „Wartung“, ist der Datastore im Wartungsmodus und sein freier Speicher wird nicht ausgewiesen. Der Missionswert ist der Standard und wird beim Bereitstellen an alle VMs der Mission vererbt. Im VM-Editor bedeutet die leere Option „Von Mission übernehmen“ und nennt den geerbten Wert in Klammern, sofern die Mission einen gesetzt hat. Wird dort ein Wert gewählt, gilt er nur für diese eine VM.',
    'location_p2' => 'Vier Dinge sind dabei wichtig:',
    'location_datacenter_optional' => 'Der Datastore der Mission ist Pflicht, das Datacenter nicht. Bleibt es leer, wird beim Bereitstellen das Datacenter des gewählten ESXi-Zugangs nur aus genau einem exakten, unterstützten und höchstens :hours Stunden alten bestätigten Namen abgeleitet. Fehlt dieser Nachweis oder ist er mehrdeutig, lehnt das Portal den Auftrag ab. Im Systemstatus stehen letzter positiver Nachweis und letzter Abrufversuch getrennt. Das gilt für alle Modi, die einen Standort lesen; der Modus „ESXi-Autostart anwenden“ schreibt nur die Startreihenfolge des Hosts und kommt ohne Datacenter und ohne Datastore aus.',
    'location_datastore_scope' => 'Ein abweichender Datastore wirkt nur beim Erstellen der VM. Eine bereits erstellte VM zieht durch eine spätere Änderung nicht auf den anderen Speicher um. Ein abweichendes Datacenter wirkt dagegen bei allen Aktionen.',
    'location_per_disk' => 'Ein eigener Datastore je Festplatte ist derzeit nicht möglich. Das Ansible-Modul für die VM-Erstellung setzt den Datastore auf VM-Ebene und übergeht damit Angaben je Festplatte. Alle Festplatten einer VM liegen also auf demselben Datastore.',
    'location_single_host' => 'Der Zielhost wird erst beim Bereitstellen gewählt, deshalb zeigt die Liste die Werte aller ESXi-Zugänge, gruppiert danach, auf wie vielen davon ein Wert vorhanden ist. „Auf allen ESXi-Zugängen vorhanden“ übersteht jede Host-Wahl. „Nur auf …“ nennt den einen Zugang mit Name und Adresse und legt damit fest, welchen Host der Auftrag später treffen muss. „Nur auf einigen Zugängen“ liegt dazwischen und nennt die betroffenen. Gezählt werden nur Zugänge, die schon einmal erfolgreich abgerufen wurden; ein nie abgerufener Zugang belegt nichts, und was es nur dort gibt, steht gar nicht erst zur Auswahl. Melden alle dasselbe, etwa das übliche ha-datacenter auf mehreren einzelnen Hosts, bleibt die Liste eine einfache Aufzählung; dann wird ein einziger Datastore vorgeschlagen und das Feld Datacenter entfällt in Mission und VM-Editor, weil es nichts ändern könnte. Steht ein Name auf mehreren Zugängen, nennt der Zusatz den kleinsten gemeldeten freien Speicher, weil noch offen ist, welcher Host es wird.',
    'location_p3' => 'Ein gespeicherter Wert, den das Inventar nicht kennt, bleibt als eigene Option mit dem Zusatz „nicht im aktuellen Inventar“ auswählbar und geht nie verloren. Solange das Inventar einer Art noch leer ist, zeigt das Feld stattdessen ein Freitextfeld, damit niemand ausgesperrt wird. Neue Werte kommen danach über einen Inventar-Abruf im Systemstatus in die Auswahl. Ein abweichender Wert erscheint dort unter „Abweichungen“ und verhindert kein Bereitstellen. Das Badge „Inventar-Abweichung“ erscheint nur bei aktuellen, qualifizierten Belegen mit Namenssemantik v2; historische Treffer bleiben als Diagnose im Systemstatus und markieren die Missionsliste nicht.',
];
